@namespace sv_999e7a1ec5784f388ce25295d83edafb.Components.Pages.Catalog

@if (TotalPages > 1)
{
    <nav class="catalog-pagination" aria-label="Product pagination">
        <button class="page-btn"
                disabled="@(CurrentPage <= 1)"
                @onclick="@(() => GoToPage(CurrentPage - 1))">
            Previous
        </button>

        @foreach (var page in GetPageNumbers())
        {
            <button class="page-btn @(page == CurrentPage ? "active" : "")"
                    @onclick="@(() => GoToPage(page))">
                @page
            </button>
        }

        <button class="page-btn"
                disabled="@(CurrentPage >= TotalPages)"
                @onclick="@(() => GoToPage(CurrentPage + 1))">
            Next
        </button>
    </nav>
}

@code {
    [Parameter]
    public int CurrentPage { get; set; } = 1;

    [Parameter]
    public int TotalCount { get; set; }

    [Parameter]
    public int PageSize { get; set; } = 12;

    [Parameter]
    public EventCallback<int> OnPageChanged { get; set; }

    private int TotalPages => (int)Math.Ceiling((double)TotalCount / PageSize);

    private IEnumerable<int> GetPageNumbers()
    {
        const int maxVisible = 7;
        if (TotalPages <= maxVisible)
            return Enumerable.Range(1, TotalPages);

        var start = Math.Max(1, CurrentPage - 3);
        var end = Math.Min(TotalPages, start + maxVisible - 1);
        if (end - start < maxVisible - 1)
            start = Math.Max(1, end - maxVisible + 1);

        return Enumerable.Range(start, end - start + 1);
    }

    private async Task GoToPage(int page)
    {
        if (page >= 1 && page <= TotalPages && page != CurrentPage)
        {
            await OnPageChanged.InvokeAsync(page);
        }
    }
}

.catalog-pagination {
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 0.25rem;
    margin-top: 2rem;
    padding: 1rem 0;
}

.page-btn {
    padding: 0.5rem 0.75rem;
    border: 1px solid #dee2e6;
    background: #fff;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
    min-width: 2.5rem;
    text-align: center;
    transition: background 0.2s, border-color 0.2s;
}

.page-btn:hover:not(:disabled):not(.active) {
    background: #e9ecef;
    border-color: #adb5bd;
}

.page-btn.active {
    background: #0d6efd;
    color: #fff;
    border-color: #0d6efd;
}

.page-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

@page "/catalog"
@namespace sv_999e7a1ec5784f388ce25295d83edafb.Components.Pages.Catalog
@rendermode InteractiveServer
@inject IProductService ProductService

<PageTitle>Product Catalog</PageTitle>

<div class="catalog-layout">
    <div class="catalog-sidebar">
        <CatalogFilters Categories="@_categories"
                        OnFiltersApplied="HandleFiltersApplied"
                        OnFiltersCleared="HandleFiltersCleared" />
    </div>

    <div class="catalog-main">
        @if (_error is not null)
        {
            <div class="catalog-error">
                <p>Something went wrong: @_error</p>
                <button @onclick="RetryLoad">Try Again</button>
            </div>
        }
        else if (_isLoading)
        {
            <div class="catalog-loading">
                <p>Loading products...</p>
            </div>
        }
        else if (_result is not null && _result.Items.Count == 0)
        {
            <div class="catalog-empty">
                <p>No products found matching your criteria.</p>
            </div>
        }
        else if (_result is not null)
        {
            <CatalogToolbar SortBy="@_sortBy"
                            TotalCount="@_result.TotalCount"
                            Page="@_currentPage"
                            PageSize="@PageSize"
                            OnSortChanged="HandleSortChanged" />

            <ProductGrid Products="@_result.Items"
                         OnProductSelected="HandleProductSelected"
                         OnAddToCart="HandleAddToCart" />

            <CatalogPagination CurrentPage="@_currentPage"
                               TotalCount="@_result.TotalCount"
                               PageSize="@PageSize"
                               OnPageChanged="HandlePageChanged" />
        }
    </div>
</div>

@code {
    private const int PageSize = 12;

    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    private List<string> _categories = [];
    private PagedResult<Product>? _result;
    private ProductFilter _currentFilter = new(null, null, null, false);
    private string _sortBy = "price_asc";
    private int _currentPage = 1;
    private bool _isLoading = true;
    private string? _error;

    protected override async Task OnInitializedAsync()
    {
        await LoadDataAsync();
    }

    private async Task LoadDataAsync()
    {
        _isLoading = true;
        _error = null;

        try
        {
            var categoriesTask = ProductService.GetCategoriesAsync();
            var productsTask = ProductService.SearchAsync(_currentFilter, _sortBy, _currentPage, PageSize);

            await Task.WhenAll(categoriesTask, productsTask);

            _categories = await categoriesTask;
            _result = await productsTask;
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _isLoading = false;
        }
    }

    private async Task SearchAsync()
    {
        _isLoading = true;
        _error = null;

        try
        {
            _result = await ProductService.SearchAsync(_currentFilter, _sortBy, _currentPage, PageSize);
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _isLoading = false;
        }
    }

    private async Task HandleFiltersApplied(ProductFilter filter)
    {
        _currentFilter = filter;
        _currentPage = 1;
        await SearchAsync();
    }

    private async Task HandleFiltersCleared()
    {
        _currentFilter = new ProductFilter(null, null, null, false);
        _currentPage = 1;
        await SearchAsync();
    }

    private async Task HandleSortChanged(string sortBy)
    {
        _sortBy = sortBy;
        _currentPage = 1;
        await SearchAsync();
    }

    private async Task HandlePageChanged(int page)
    {
        _currentPage = page;
        await SearchAsync();
    }

    private async Task HandleProductSelected(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private Task HandleAddToCart(Product product)
    {
        // Placeholder for add-to-cart logic
        return Task.CompletedTask;
    }

    private async Task RetryLoad()
    {
        await LoadDataAsync();
    }
}

.catalog-layout {
    display: flex;
    gap: 2rem;
    padding: 1.5rem;
    max-width: 1400px;
    margin: 0 auto;
}

.catalog-sidebar {
    flex: 0 0 25%;
    min-width: 250px;
}

.catalog-main {
    flex: 1;
    min-width: 0;
}

.catalog-loading,
.catalog-empty,
.catalog-error {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 3rem;
    text-align: center;
    color: #555;
    background: #f8f9fa;
    border-radius: 8px;
    border: 1px solid #e0e0e0;
}

.catalog-error {
    color: #dc3545;
}

.catalog-error button {
    margin-top: 1rem;
    padding: 0.5rem 1rem;
    background: #0d6efd;
    color: #fff;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

@namespace sv_999e7a1ec5784f388ce25295d83edafb.Components.Pages.Catalog

<div class="product-card" @onclick="HandleCardClick">
    <div class="product-image" role="img" aria-label="@Product.Name">
